<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {ElButton,ElInput,ElForm,ElFormItem,ElSwitch,ElSelect,ElOption,ElAlert,ElSkeleton,ElMessage,ElMessageBox,ElTag} from 'element-plus';
import AppearancePicker from './AppearancePicker.vue';
import {errorMessage} from './apiErrors.js';
import ImageGallery from './ImageGallery.vue';
import RichTextEditor from './RichTextEditor.vue';
import HomepageModules from './HomepageModules.vue';

const props=defineProps({eventId:{type:Number,required:true},websiteUrl:String,language:{type:String,default:'zh'}});
const t=(zh,en)=>props.language==='en'?en:zh;
const loading=ref(true),saving=ref(false),uploads=ref(0),readOnly=ref(false),error=ref(''),revision=ref(0),template=ref('academic-full'),content=ref(null),saved=ref('');
const registrationUrl=ref(''),submissionUrl=ref('');
const appearances=ref([]),previewing=ref(false),appearanceUpgrade=ref(false);
const api=computed(()=>`/api/conferences/${props.eventId}/content`);
const snapshot=()=>JSON.stringify({template:template.value,content:content.value});
const dirty=computed(()=>content.value!==null&&saved.value!==snapshot());
const disabled=computed(()=>saving.value||readOnly.value||!!uploads.value||previewing.value);
const sectionLabels={introduction:['会议简介','Introduction'],speakers:['大会嘉宾','Speakers'],news:['会议动态','News'],notices:['参会须知','Participant information'],venue:['会场与酒店','Venue & hotels'],committees:['会议组织及成员','Committees & members'],topics:['征稿范围与主题','Topics & scope'],industry:['地方产业与技术需求','Industry & technology needs'],showcase:['科技成果展示与征集','Research showcase'],matchmaking:['产业对接与意向登记','Industry matchmaking'],audience:['参会对象','Who should attend'],highlights:['会议亮点','Highlights'],registration_info:['报名须知','Registration instructions'],submission_info:['投稿须知','Submission instructions']};
const collections=[
 {key:'speakers',title:['大会嘉宾','Speakers'],singular:['嘉宾','speaker'],empty:()=>({name:'',name_en:'',affiliation:'',affiliation_en:'',topic:'',topic_en:'',role:'',role_en:'',bio:'',bio_en:'',image:'',enabled:true}),fields:[{key:'name',label:['姓名与职称','Name']},{key:'role',label:['嘉宾角色','Speaker role'],limit:200},{key:'affiliation',label:['头衔、所属单位及来源国','Affiliation']},{key:'topic',label:['报告主题','Presentation topic']},{key:'bio',label:['嘉宾简介（1000字以内）','Biography (up to 1,000 characters)'],limit:1000,multiline:true}],image:true},
 {key:'news',title:['会议动态','News'],singular:['动态','news item'],empty:()=>({title:'',title_en:'',date:'',body:'',body_en:'',url:'',enabled:true}),fields:[{key:'title',label:['标题','Title']},{key:'date',label:['发布日期','Publication date'],type:'date',english:false},{key:'body',label:['内容','Content'],multiline:true},{key:'url',label:['详情链接（可选）','Details link (optional)'],english:false}]},
 {key:'dates',title:['重要日期','Important dates'],singular:['日期','date'],empty:()=>({label:'',label_en:'',date:'',end_date:'',enabled:true}),fields:[{key:'label',label:['日期说明','Label']},{key:'date',label:['日期（保留已有日期说明）','Date'],english:false},{key:'end_date',label:['结束日期（范围可选）','End date (optional)'],type:'date',english:false}]}
];
function move(list,index,offset){const next=index+offset;if(next<0||next>=list.length)return;list.splice(next,0,list.splice(index,1)[0]);}
async function remove(list,index){try{await ElMessageBox.confirm(t('删除此项后，保存才会更新网站。','The item will be removed from the website when you save.'),t('删除项目','Remove item'),{confirmButtonText:t('删除','Remove'),cancelButtonText:t('取消','Cancel'),type:'warning'});list.splice(index,1);}catch{}}
async function request(url,options={},asText=false){
 const headers={...options.headers};
 if(options.method){const session=await window.MeetPortal.refreshSession();if(!session?.user)throw new Error(t('登录状态已失效，请重新登录。草稿仍保留在此页。','Your session expired. Log in again; your draft remains on this page.'));headers['X-CSRF-Token']=session.csrf_token;if(!(options.body instanceof FormData))headers['Content-Type']='application/json';}
 const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers});
 if(!response.ok){
  if(response.status===403)readOnly.value=true;
  let detail='';try{detail=errorMessage(await response.json(),'');}catch{}
  const message=response.status===409?t('其他管理者已保存了新版本。您的草稿已保留；请先复制需要保留的文字，再点击“重新载入”查看最新版本。','Another organizer saved a newer version. Your draft is retained. Copy any text you need before reloading the latest version.'):response.status===403?t('您没有编辑权限，或会议已锁定。草稿已保留。','You do not have editing permission, or this conference is locked. Your draft is retained.'):response.status===401?t('请重新登录后继续，草稿已保留。','Log in again to continue. Your draft is retained.'):detail||t('操作未完成，请检查填写的信息后重试。草稿已保留。','The operation failed. Check the details and try again. Your draft is retained.');
  throw new Error(message);
 }
 return asText?response.text():response.json();
}
function apply(data){template.value=data.template;revision.value=data.revision;content.value=data.content;appearances.value=data.appearances||[];registrationUrl.value=data.registration_url;submissionUrl.value=data.submission_url;appearanceUpgrade.value=false;saved.value=snapshot();}
function selectAppearance(item){if(disabled.value)return;content.value.theme={...content.value.theme,layout:item.layout,accent:item.accent};if(template.value!=='academic-full'){template.value='academic-full';appearanceUpgrade.value=true;}}
async function previewAppearance(){
 previewing.value=true;error.value='';
 try{return await request(`/api/conferences/${props.eventId}/appearance-preview`,{method:'POST',body:JSON.stringify({theme:content.value.theme})},true);}catch(e){error.value=e.message;throw e;}finally{previewing.value=false;}
}
async function load(){
 if(dirty.value){try{await ElMessageBox.confirm(t('重新载入会放弃此页尚未保存的修改。','Reloading discards the unsaved changes on this page.'),t('重新载入最新版本','Reload latest version'),{confirmButtonText:t('放弃修改并载入','Discard and reload'),cancelButtonText:t('保留草稿','Keep draft'),type:'warning'});}catch{return;}}
 loading.value=true;error.value='';readOnly.value=false;
 try{apply(await request(api.value));}catch(e){error.value=e.message;}finally{loading.value=false;}
}
async function save(){
 if(disabled.value)return;saving.value=true;error.value='';
 try{apply(await request(api.value,{method:'PUT',body:JSON.stringify({revision:revision.value,template:template.value,content:content.value})}));ElMessage.success(t('首页设计已保存','Homepage design saved'));}catch(e){error.value=e.message;await nextTick();document.querySelector('[data-test=content-error]')?.scrollIntoView({block:'center'});}finally{saving.value=false;}
}
async function upload(event,target,key){
 const file=event.target.files?.[0];event.target.value='';if(!file)return;
 try{target[key]=await uploadFile(file);ElMessage.success(t('图片已上传，请保存首页设计。','Image uploaded. Save the homepage design to use it.'));}catch(e){error.value=e.message;}
}
async function uploadFile(file){
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error(t('请选择不超过 5 MiB 的 PNG、JPEG 或 WebP 图片。','Choose a PNG, JPEG or WebP image up to 5 MiB.'));
 uploads.value++;error.value='';
 try{const data=new FormData();data.append('file',file);const result=await request(`/api/conferences/${props.eventId}/assets`,{method:'POST',body:data});return result.url;}catch(e){error.value=e.message;throw e;}finally{uploads.value--;}
}
async function preview(){
 if(dirty.value){try{await ElMessageBox.confirm(t('预览展示上一次保存的版本，此页尚未保存的修改不会显示。','Preview shows the last saved version. Unsaved changes on this page will not appear.'),t('预览已保存的网站','Preview saved website'),{confirmButtonText:t('查看已保存版本','View saved version'),cancelButtonText:t('继续编辑','Continue editing'),type:'info'});}catch{return;}}
 window.open(props.websiteUrl||`/event/${props.eventId}/`,'_blank','noopener');
}
function beforeUnload(event){if(dirty.value||uploads.value){event.preventDefault();event.returnValue='';}}
function addOrganization(){content.value.organizations.push({title:'',title_en:'',enabled:true,items:[]});}
function addOrganizationItem(group){group.items.push({name:'',name_en:'',image:'',images:[],url:'',description:'',description_en:'',enabled:true});}
defineExpose({preview});
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);load();});
onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload));
</script>

<template>
 <section class="site-editor" data-test="site-editor" :data-ready="!loading&&content?'true':null">
  <div class="site-editor-toolbar surface">
   <div><h2>{{t('首页设计','Homepage design')}}</h2><p>{{t('维护首页内容、图片与报名投稿入口，保存后即可预览。','Edit homepage content, images and registration or submission links. Save to preview.')}}</p><ElTag v-if="dirty" type="warning" size="small">{{t('有未保存的修改','Unsaved changes')}}</ElTag></div>
   <div class="site-editor-buttons"><ElButton :disabled="loading||saving||!!uploads||previewing" @click="load">{{t('重新载入','Reload')}}</ElButton><ElButton :disabled="loading||previewing" @click="preview">{{t('预览已保存版本','Preview saved version')}}</ElButton><ElButton type="primary" data-test="save-content" :loading="saving" :disabled="loading||!content||disabled||!dirty" @click="save">{{t('保存首页设计','Save homepage')}}</ElButton></div>
  </div>
  <ElAlert v-if="error" :title="error" type="error" :closable="false" show-icon class="site-editor-alert" data-test="content-error"/>
  <ElAlert v-if="uploads" :title="t('图片正在上传，请稍候再保存或离开此页。','An image is uploading. Wait before saving or leaving this page.')" type="info" :closable="false" class="site-editor-alert"/>
  <ElSkeleton v-if="loading" :rows="8" animated/>
  <template v-else-if="content">
   <div class="site-template-choice surface"><div><strong>{{t('网站模板','Website template')}}</strong><p>{{t('完整学术模板包含横幅、嘉宾、动态和单位侧栏。切换并保存会补齐缺少的栏目，保留已有页面内容。','The complete academic template includes a banner, speakers, news and organization sidebar. Saving adds missing sections while preserving existing pages.')}}</p></div><ElSelect v-model="template" :disabled="disabled" :aria-label="t('网站模板','Website template')"><ElOption value="academic-full" :label="t('完整学术会议','Complete academic conference')"/><ElOption value="academic" :label="t('学术蓝','Academic blue')"/><ElOption value="industry" :label="t('科技绿','Technology green')"/></ElSelect></div>
   <ElAlert v-if="template!=='academic-full'" type="info" :closable="false" show-icon class="site-editor-alert"><template #title>{{t('当前模板保留原有页面展示。选择完整学术模板并保存后，下方首页内容才会应用。','Your current template keeps its original presentation. Choose and save the complete academic template to use the homepage content below.')}}</template><ElButton data-test="use-full-template" :disabled="disabled" @click="template='academic-full'">{{t('使用完整学术模板','Use complete academic template')}}</ElButton></ElAlert>
   <AppearancePicker :appearances="appearances" :theme="content.theme" :disabled="disabled" :language="language" :preview="previewAppearance" @select="selectAppearance"/>
   <ElAlert v-if="appearanceUpgrade" :title="t('已切换为完整学术模板；保存后应用外观。','Switched to the complete academic template. Save to apply the appearance.')" type="info" :closable="false" show-icon class="site-editor-alert"/>
   <ElForm :disabled="disabled" label-position="top" class="site-content-form">
    <section class="surface site-editor-section">
     <div class="site-section-title"><div><h3>{{t('会议横幅','Conference banner')}}</h3><p>{{t('上传会议主视觉，保留图片原有比例。已有标题的图片可关闭叠加标题。','Upload your conference artwork. Images keep their original proportions; turn off the title if it is already in the image.')}}</p></div><ElSwitch v-model="content.banner.show_title" :active-text="t('叠加标题与日期','Overlay title & dates')"/></div>
     <div class="site-fields"><ElFormItem :label="t('会议标题','Conference title')" data-test="banner-title"><ElInput v-model="content.banner.title" maxlength="300"/></ElFormItem><ElFormItem :label="t('副标题','Subtitle')"><ElInput v-model="content.banner.subtitle" maxlength="500"/></ElFormItem></div>
     <div class="site-image-field"><label>{{t('中文横幅','Chinese banner')}}</label><div v-if="content.banner.image" class="site-image-preview banner"><img :src="content.banner.image" :alt="t('中文横幅预览','Chinese banner preview')"/><ElButton :disabled="disabled" @click="content.banner.image=''">{{t('移除图片','Remove image')}}</ElButton></div><label class="site-upload-button"><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="disabled||!!uploads" data-test="banner-upload" @change="upload($event,content.banner,'image')"/><span>{{content.banner.image?t('替换横幅','Replace banner'):t('上传横幅','Upload banner')}}</span></label><small>PNG / JPEG / WebP · ≤ 5 MiB · {{t('最多 2000 万像素','Up to 20 million pixels')}}</small></div>
     <details class="site-english"><summary>{{t('英文横幅与文字（可选）','English banner and text (optional)')}}</summary><p>{{t('英文留空时显示对应的中文内容。','Blank English fields use the corresponding Chinese content.')}}</p><div class="site-fields"><ElFormItem label="Conference title (English)"><ElInput v-model="content.banner.title_en" maxlength="300"/></ElFormItem><ElFormItem label="Subtitle (English)"><ElInput v-model="content.banner.subtitle_en" maxlength="500"/></ElFormItem></div><div class="site-image-field"><label>English banner</label><div v-if="content.banner.image_en" class="site-image-preview banner"><img :src="content.banner.image_en" alt="English banner preview"/><ElButton :disabled="disabled" @click="content.banner.image_en=''">{{t('移除图片','Remove image')}}</ElButton></div><label class="site-upload-button"><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="disabled||!!uploads" @change="upload($event,content.banner,'image_en')"/><span>{{t('上传英文横幅','Upload English banner')}}</span></label></div></details>
     <ElFormItem :label="t('栏目强调色','Section accent color')"><div class="site-color-field"><input v-model="content.theme.accent" type="color" :disabled="disabled" :aria-label="t('栏目强调色','Section accent color')"/><span>{{content.theme.accent}}</span></div></ElFormItem>
    </section>

    <section class="surface site-editor-section"><div class="site-section-title"><div><h3>{{t('首页模块','Homepage sections')}}</h3><p>{{t('调整正文模块的顺序与显隐。没有内容的模块不会显示空框。','Set the order and visibility of main sections. Empty sections do not leave blank panels.')}}</p></div></div><div v-for="(section,index) in content.sections" :key="section.key" class="site-order-row" :data-test="`section-${section.key}`"><span>{{t(...sectionLabels[section.key])}}</span><ElSwitch v-model="section.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||index===0" @click="move(content.sections,index,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||index===content.sections.length-1" @click="move(content.sections,index,1)">{{t('下移','Move down')}}</ElButton></div><p class="site-field-note">{{t('中文会议简介在会议基本设置中维护。','Edit the Chinese conference introduction in conference settings.')}} <a :href="`/conference/${eventId}/?tab=settings#conference-basic`">{{t('编辑会议简介与基本信息','Edit introduction & basic information')}}</a></p><details class="site-english"><summary>{{t('英文会议简介（可选）','English introduction (optional)')}}</summary><ElFormItem label="Introduction (English)"><ElInput v-model="content.introduction_en" type="textarea" :rows="5" maxlength="20000" show-word-limit/></ElFormItem></details><ImageGallery v-model="content.introduction_images" :upload="uploadFile" :disabled="disabled" :language="language" :label="t('简介图片（显示在文字之前）','Introduction images (before text)')" data-test="gallery-introduction"/></section>

    <section class="surface site-editor-section" data-test="countdown-settings"><div class="site-section-title"><div><h3>{{t('会议倒计时','Conference countdown')}}</h3><p>{{t('在会议首页显示独立横条，每秒更新天、时、分、秒。','Show a separate countdown bar on the homepage, updated every second.')}}</p></div><ElSwitch v-model="content.countdown.enabled" :active-text="t('显示倒计时','Show countdown')" data-test="countdown-enabled"/></div><ElFormItem :label="t('目标日期（可选）','Target date (optional)')"><ElInput v-model="content.countdown.target_date" type="date" data-test="countdown-date"/></ElFormItem><p class="site-native-links">{{t('留空时跟随会议开始日期；统一倒数至目标日北京时间 00:00。到期后显示结束提示。','Leave blank to follow the conference start date. Counts down to 00:00 Beijing time on that date, then displays an end message.')}}</p></section>
    <section v-for="collection in collections" :key="collection.key" class="surface site-editor-section" :data-test="`list-${collection.key}`"><div class="site-section-title"><div><h3>{{t(...collection.title)}} <span class="site-item-count">{{content[collection.key].length}}</span></h3><p>{{t('添加真实内容；关闭“显示”可保留资料并暂时隐藏。','Add real content. Turn off “Show” to keep an item hidden without deleting it.')}}</p></div><ElButton :data-test="`add-${collection.key==='speakers'?'speaker':collection.key==='news'?'news':'date'}`" :disabled="disabled" @click="content[collection.key].push(collection.empty())">{{t('添加','Add ')}}{{t(...collection.singular)}}</ElButton></div><p v-if="!content[collection.key].length" class="site-empty">{{t('尚未添加内容。','No items yet.')}}</p><article v-for="(item,index) in content[collection.key]" :key="index" class="site-list-item" :data-test="`${collection.key}-item`"><div class="site-item-toolbar"><strong>{{t(...collection.singular)}} {{index+1}}</strong><div><ElSwitch v-model="item.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||index===0" @click="move(content[collection.key],index,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||index===content[collection.key].length-1" @click="move(content[collection.key],index,1)">{{t('下移','Move down')}}</ElButton><ElButton type="danger" plain :disabled="disabled" @click="remove(content[collection.key],index)">{{t('删除','Remove')}}</ElButton></div></div><div class="site-fields"><ElFormItem v-for="field in collection.fields" :key="field.key" :label="t(...field.label)" :class="{'site-field-wide':field.multiline}" :data-test="collection.key==='speakers'&&field.key==='name'?'speaker-name':`${collection.key}-${field.key}`"><ElInput v-model="item[field.key]" :type="field.multiline?'textarea':field.key==='date'&&collection.key==='dates'&&(!item.date||/^\d{4}-\d{2}-\d{2}$/.test(item.date))?'date':field.type||'text'" :rows="field.multiline?4:undefined" :maxlength="field.limit||(field.multiline?10000:field.key==='url'?2000:500)" :show-word-limit="field.multiline"/></ElFormItem></div><div v-if="collection.image" class="site-image-field"><label>{{t('嘉宾照片','Speaker photo')}}</label><div v-if="item.image" class="site-image-preview"><img :src="item.image" :alt="item.name||t('嘉宾照片预览','Speaker photo preview')"/><ElButton :disabled="disabled" @click="item.image=''">{{t('移除图片','Remove image')}}</ElButton></div><label class="site-upload-button"><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="disabled||!!uploads" @change="upload($event,item,'image')"/><span>{{t('上传照片','Upload photo')}}</span></label></div><details class="site-english"><summary>{{t('英文内容（可选）','English content (optional)')}}</summary><div class="site-fields"><ElFormItem v-for="field in collection.fields.filter(field=>field.english!==false)" :key="field.key" :label="`${field.label[1]} (English)`" :class="{'site-field-wide':field.multiline}"><ElInput v-model="item[`${field.key}_en`]" :type="field.multiline?'textarea':'text'" :rows="field.multiline?4:undefined" :maxlength="field.limit||(field.multiline?10000:500)" :show-word-limit="field.multiline"/></ElFormItem></div></details></article></section>

    <section class="surface site-editor-section" data-test="organizations"><div class="site-section-title"><div><h3>{{t('单位分组与 Logo','Organization groups & logos')}}</h3><p>{{t('可添加主办、承办、协办和媒体支持等分组。专业技术支持用于高校实验室、技术研究院等；产业支持用于协会、企业、园区和联盟。每组最多50家单位，单位可上传多张期刊封面或检索页面。','Create organizer, host, co-organizer and media groups. Academic support includes labs and institutes; industry support includes associations, companies and parks. Up to 50 organizations per group, each with multiple images.')}}</p></div><ElButton :disabled="disabled||content.organizations.length>=20" data-test="add-organization" @click="addOrganization">{{t('添加分组','Add group')}}</ElButton></div><article v-for="(group,index) in content.organizations" :key="index" class="site-list-item" data-test="organization-group"><div class="site-item-toolbar"><strong>{{group.title||t('新分组','New group')}}</strong><div><ElSwitch v-model="group.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||index===0" @click="move(content.organizations,index,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||index===content.organizations.length-1" @click="move(content.organizations,index,1)">{{t('下移','Move down')}}</ElButton><ElButton type="danger" plain :disabled="disabled" @click="remove(content.organizations,index)">{{t('删除','Remove')}}</ElButton></div></div><ElFormItem :label="t('分组名称','Group title')"><ElInput v-model="group.title" maxlength="300"/></ElFormItem><details class="site-english"><summary>{{t('英文分组名称（可选）','English group title (optional)')}}</summary><ElFormItem label="Group title (English)"><ElInput v-model="group.title_en" maxlength="300"/></ElFormItem></details><article v-for="(item,itemIndex) in group.items" :key="itemIndex" class="site-organization-item" data-test="organization-item"><div class="site-item-toolbar"><strong>{{t('单位','Organization')}} {{itemIndex+1}}</strong><div><ElSwitch v-model="item.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||itemIndex===0" @click="move(group.items,itemIndex,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||itemIndex===group.items.length-1" @click="move(group.items,itemIndex,1)">{{t('下移','Move down')}}</ElButton><ElButton type="danger" plain :disabled="disabled" @click="remove(group.items,itemIndex)">{{t('删除','Remove')}}</ElButton></div></div><div class="site-fields"><ElFormItem :label="t('单位名称','Organization name')"><ElInput v-model="item.name" maxlength="500"/></ElFormItem><ElFormItem :label="t('单位网址（可选）','Website (optional)')"><ElInput v-model="item.url" maxlength="2000" placeholder="https://"/></ElFormItem><ElFormItem :label="t('单位简介（300字以内）','Organization introduction (up to 300 characters)')" class="site-field-wide"><ElInput v-model="item.description" type="textarea" :rows="3" maxlength="300" show-word-limit/></ElFormItem></div><details class="site-english"><summary>{{t('英文单位名称（可选）','English organization name (optional)')}}</summary><ElFormItem label="Organization name (English)"><ElInput v-model="item.name_en" maxlength="500"/></ElFormItem><ElFormItem label="Organization introduction (English)"><ElInput v-model="item.description_en" type="textarea" :rows="3" maxlength="300" show-word-limit/></ElFormItem></details><div class="site-image-field"><label>{{t('单位 Logo','Organization logo')}}</label><div v-if="item.image" class="site-image-preview"><img :src="item.image" :alt="item.name||t('Logo 预览','Logo preview')"/><ElButton :disabled="disabled" @click="item.image=''">{{t('移除图片','Remove image')}}</ElButton></div><label class="site-upload-button"><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="disabled||!!uploads" @change="upload($event,item,'image')"/><span>{{t('上传 Logo','Upload logo')}}</span></label></div><ImageGallery v-model="item.images" :upload="uploadFile" :disabled="disabled" :language="language" :label="t('更多图片／期刊封面与检索页面','Additional images / journal covers & indexing')" data-test="organization-images"/></article><ElButton :disabled="disabled||group.items.length>=50" data-test="add-organization-item" @click="addOrganizationItem(group)">{{t('添加单位','Add organization')}}</ElButton></article></section>

    <section class="surface site-editor-section"><div class="site-section-title"><h3>{{t('联系信息','Contact information')}}</h3><ElSwitch v-model="content.contact.enabled" :active-text="t('显示','Show')"/></div><div class="site-fields"><ElFormItem :label="t('联系人','Contact name')"><ElInput v-model="content.contact.name" maxlength="500"/></ElFormItem><ElFormItem :label="t('联系电话','Phone')"><ElInput v-model="content.contact.phone" maxlength="200"/></ElFormItem><ElFormItem :label="t('电子邮箱','Email')"><ElInput v-model="content.contact.email" type="email" maxlength="254"/></ElFormItem><ElFormItem :label="t('联系地址','Address')"><ElInput v-model="content.contact.address" maxlength="500"/></ElFormItem></div><RichTextEditor v-model="content.contact.html" :disabled="disabled" :language="language" data-test="contact-richtext"/><ImageGallery v-model="content.contact.images" :upload="uploadFile" :disabled="disabled" :language="language" :label="t('联系信息图片','Contact images')"/><details class="site-english"><summary>{{t('英文联系信息（可选）','English contact information (optional)')}}</summary><div class="site-fields"><ElFormItem label="Contact name (English)"><ElInput v-model="content.contact.name_en" maxlength="500"/></ElFormItem><ElFormItem label="Address (English)"><ElInput v-model="content.contact.address_en" maxlength="500"/></ElFormItem></div><RichTextEditor v-model="content.contact.html_en" :disabled="disabled" language="en"/></details></section>

    <section v-for="entry in [{key:'notices',field:'text',label:['参会须知','Participant information']},{key:'venue',field:'description',label:['会场与酒店信息','Venue & hotel information']}]" :key="entry.key" class="surface site-editor-section"><div class="site-section-title"><h3>{{t(...entry.label)}}</h3><ElSwitch v-model="content[entry.key].enabled" :active-text="t('显示','Show')"/></div><ElFormItem :label="t('中文内容','Chinese content')"><ElInput v-model="content[entry.key][entry.field]" type="textarea" :rows="5" maxlength="10000" show-word-limit/></ElFormItem><details class="site-english"><summary>{{t('英文内容（可选）','English content (optional)')}}</summary><ElFormItem label="Content (English)"><ElInput v-model="content[entry.key][`${entry.field}_en`]" type="textarea" :rows="5" maxlength="10000" show-word-limit/></ElFormItem></details><ImageGallery v-if="entry.key==='venue'" v-model="content.venue.images" :upload="uploadFile" :disabled="disabled" :language="language" :label="t('会场与酒店图片','Venue & hotel images')"/></section>

    <section class="surface site-editor-section" data-test="entry-actions"><div class="site-section-title"><div><h3>{{t('报名与投稿入口','Registration & submission links')}}</h3><p>{{t('在“首页模块”中可将须知设为独立板块。开启下方入口后显示直达按钮；是否开放以实际表单和日期为准。','Enable instructions as independent homepage sections above. Enable the links below to show direct buttons; availability follows your forms and dates.')}}</p></div></div><article v-for="action in [{key:'registration',label:['会议报名','Registration'],native:registrationUrl,manage:`/event/${eventId}/manage/registration/`},{key:'submission',label:['摘要投稿','Abstract submission'],native:submissionUrl,manage:`/event/${eventId}/manage/abstracts/`}]" :key="action.key" class="site-list-item"><div class="site-section-title"><h4>{{t(...action.label)}}</h4><ElSwitch v-model="content.actions[action.key].enabled" :active-text="t('显示入口','Show link')" :data-test="`${action.key}-enabled`"/></div><ElFormItem :label="action.key==='registration'?t('报名须知','Registration instructions'):t('投稿须知','Submission instructions')"><ElInput v-model="content.actions[action.key].text" type="textarea" :rows="4" maxlength="10000" show-word-limit :placeholder="action.key==='registration'?t('说明作者、口头演讲、海报和听众的参会方式及报名要求。','Describe author, oral, poster and audience participation requirements.'):t('说明投稿语言、页数、查重和排版模板要求。','Describe language, page limits, originality and template requirements.')"/></ElFormItem><details class="site-english"><summary>{{t('英文须知（可选）','English instructions (optional)')}}</summary><ElInput v-model="content.actions[action.key].text_en" type="textarea" :rows="4" maxlength="10000"/></details><ElFormItem :label="t('入口方式','Link type')"><ElSelect v-model="content.actions[action.key].mode" :data-test="`${action.key}-mode`"><ElOption value="native" :label="t('使用平台原生功能','Use platform feature')"/><ElOption value="external" :label="t('使用外部链接','Use external link')"/></ElSelect></ElFormItem><ElFormItem v-if="content.actions[action.key].mode==='external'" :label="t('外部地址','External URL')"><ElInput v-model="content.actions[action.key].url" maxlength="2000" :placeholder="action.key==='submission'?'https:// / mailto:':'https://'" :data-test="`${action.key}-url`"/></ElFormItem><p v-else class="site-native-links"><a :href="action.manage" target="_blank" rel="noopener">{{t('打开原生配置','Open native configuration')}} ↗</a><a :href="action.native" target="_blank" rel="noopener">{{t('查看参会者入口','View participant link')}} ↗</a></p></article></section>
    <HomepageModules :content="content" :disabled="disabled" :language="language" :event-id="eventId" @remove="remove" @move="move"/>
   </ElForm>
   <div class="site-editor-footer surface"><span>{{dirty?t('有未保存的修改；离开此页会提示您。','Unsaved changes. You will be prompted before leaving.'):t('所有修改已保存。预览展示当前已保存的网站。','All changes saved. Preview shows the saved website.')}}</span><ElButton type="primary" :loading="saving" :disabled="loading||disabled||!dirty" @click="save">{{t('保存首页设计','Save homepage')}}</ElButton></div>
  </template>
 </section>
</template>

<style>
.site-editor{min-width:0;color:#344f65}.site-editor .surface{margin-bottom:20px}.site-editor-toolbar,.site-template-choice,.site-editor-footer{padding:24px;display:flex;align-items:center;justify-content:space-between;gap:20px}.site-editor h2{margin:0 0 8px;font-size:18px}.site-editor p{line-height:1.8}.site-editor-toolbar p,.site-template-choice p,.site-section-title p{margin:0;color:#7d8e9d;font-size:12px;max-width:700px}.site-editor-buttons{display:flex;gap:8px;flex-wrap:wrap;flex-shrink:0}.site-editor .el-button+.el-button{margin-left:0}.site-editor-alert{margin-bottom:20px}.site-template-choice>.el-select{max-width:270px;width:100%;flex-shrink:0}.site-template-choice strong{display:block;margin-bottom:8px}.site-editor-section{padding:26px}.site-section-title{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:20px}.site-section-title>.el-switch{flex-shrink:0}.site-editor .el-switch__label{white-space:nowrap}.site-section-title h3,.site-section-title h4{margin:0;font-size:16px;color:#24465e;font-weight:600}.site-section-title h3+p{margin-top:7px}.site-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 22px}.site-field-wide{grid-column:1/-1}.site-editor .el-input,.site-editor .el-textarea,.site-editor .el-select{min-width:0;width:100%}.site-editor .el-form-item__label{font-size:12px;color:#5e7587}.site-image-field{margin-bottom:20px}.site-image-field>label:first-child{font-size:12px;display:block;margin-bottom:10px}.site-image-field>small{display:block;color:#8b9aa7;font-size:11px;margin-top:8px}.site-upload-button{display:inline-flex;position:relative;align-items:center;justify-content:center;border:1px solid #bacbd7;border-radius:4px;color:#416d88;background:#fff;padding:9px 14px;cursor:pointer;font-size:12px;overflow:hidden}.site-upload-button:focus-within{outline:2px solid #448fb3;outline-offset:2px}.site-upload-button:has(input:disabled){opacity:.55;cursor:not-allowed}.site-upload-button input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:inherit}.site-image-preview{display:flex;align-items:center;gap:15px;margin-bottom:12px;flex-wrap:wrap}.site-image-preview img{width:110px;height:110px;object-fit:contain;border:1px solid #e5ebf0;border-radius:4px;background:#f7fafc}.site-image-preview.banner img{height:auto;width:100%;max-width:560px;max-height:240px;object-fit:contain;object-position:left}.site-english{border:1px solid #e8edf1;border-radius:5px;margin:12px 0 20px;padding:12px 15px;background:#fafcfd}.site-english summary{font-size:12px;color:#52758c;cursor:pointer;line-height:1.6}.site-english[open] summary{margin-bottom:16px}.site-english p{font-size:11px;color:#8b9aa7}.site-english .el-form-item:last-child{margin-bottom:5px}.site-color-field{display:flex;align-items:center;gap:12px;color:#7d8e9d;font-size:12px}.site-color-field input{width:48px;height:32px;padding:2px;border:1px solid #dce4ec;background:white;border-radius:4px}.site-order-row{display:flex;align-items:center;gap:10px;padding:14px 0;border-bottom:1px solid #edf1f5}.site-order-row>span{flex:1;min-width:0;font-size:13px}.site-field-note{font-size:12px;color:#7d8e9d;margin:18px 0 0}.site-editor a{color:#3c82a5;text-decoration:none}.site-editor a:hover{text-decoration:underline}.site-list-item{background:#fbfcfd;border:1px solid #e4ebf0;border-radius:7px;padding:20px;margin-top:16px}.site-item-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.site-item-toolbar strong{font-size:13px;overflow-wrap:anywhere}.site-item-toolbar>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.site-list-item .el-switch{margin-right:8px}.site-item-count{font-size:12px;color:#8b9aa7;font-weight:400;margin-left:7px}.site-empty{font-size:12px;color:#8b9aa7;padding:20px;background:#f7fafc;border-radius:5px;margin:0}.site-organization-item{margin:18px 0;padding:18px;border:1px solid #e4ebf0;border-radius:5px;background:white}.site-native-links{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;margin-bottom:0}.site-editor-footer{font-size:12px;color:#7d8e9d;position:sticky;bottom:12px;z-index:3;box-shadow:0 3px 18px #16334d0d}.site-editor-footer>.el-button{flex-shrink:0}
@media(max-width:1050px){.site-editor-toolbar,.site-template-choice{align-items:flex-start;flex-direction:column}.site-editor-buttons{flex-shrink:1}.site-item-toolbar{align-items:flex-start;flex-direction:column}}
@media(max-width:600px){.site-editor-toolbar,.site-template-choice,.site-editor-section,.site-editor-footer{padding:18px}.site-editor-buttons{width:100%}.site-editor-buttons>.el-button{flex:1;padding:8px;font-size:11px}.site-editor-buttons>.el-button:first-child{flex:0 0 auto}.site-fields{grid-template-columns:1fr}.site-section-title{align-items:flex-start;gap:10px}.site-section-title h3{font-size:14px}.site-section-title p{font-size:11px}.site-section-title>.el-button{padding:8px;flex-shrink:0}.site-list-item{padding:14px}.site-organization-item{padding:12px}.site-item-toolbar>div{gap:6px;width:100%}.site-item-toolbar .el-button{padding:7px;font-size:11px}.site-item-toolbar .el-switch{margin-right:auto}.site-order-row{gap:7px;flex-wrap:wrap}.site-order-row>span{flex-basis:calc(100% - 90px)}.site-order-row>.el-button{flex:1;padding:7px}.site-editor-footer{gap:10px;bottom:0;padding:14px}.site-editor-footer>span{font-size:10px}.site-editor-footer>.el-button{font-size:11px;padding:8px}.site-english{padding:10px}.site-editor h2{font-size:16px}}
